const NOMBRE = 'Galp';
const leer = (nodo) => { try { return $(nodo).first().json; } catch (e) { return null; } };
const texto = (e) => String(e == null ? '' : typeof e === 'string' ? e : (e.message || JSON.stringify(e))).slice(0, 400);
const d = leer('Descargar facturas de Galp') || {};
const envio = leer('Enviar facturas de Galp a Trans2000');
const files = Array.isArray(d.files) ? d.files : [];
const quien = (f) => f.empresa || f.usuario || '?';
const r = {
  proveedor: NOMBRE,
  estado: 'ok',
  periodo: (d.desde || '-') + ' a ' + (d.hasta || '-'),
  detalle: [],
  nuevos: 0,
  actualizados: 0,
  nIncidencias: 0,
  incidencias: [],
  errores: [],
  avisos: Array.isArray(d.avisos) ? d.avisos : [],
  omitidas: (Array.isArray(d.omitidas) ? d.omitidas : []).filter((o) => String(o).toLowerCase().indexOf('sin facturas entre') < 0),
  mensajes: [],
};
if (d.error && /tiene facturas entre/.test(texto(d.error))) {
  r.estado = 'sin_datos';
} else if (d.error) {
  r.estado = 'error';
  r.errores.push('Descarga' + (d.step ? ' (' + d.step + ')' : '') + ': ' + texto(d.error));
} else if (!files.length) {
  r.estado = 'sin_datos';
} else if (!envio) {
  r.estado = 'error';
  r.errores.push('Los ficheros se descargaron pero no se enviaron a Trans2000');
} else {
  r.detalle = Array.isArray(envio.detalle) ? envio.detalle : files.map((f) => quien(f) + ': factura ' + (f.factura || '?') + ' (' + (f.fecha_factura || 'sin fecha') + ')');
  r.nuevos = Number(envio.nuevos) || 0;
  r.actualizados = Number(envio.actualizados) || 0;
  r.incidencias = Array.isArray(envio.incidencias_detalle) ? envio.incidencias_detalle : [];
  r.nIncidencias = r.incidencias.length || Number(envio.incidencias) || 0;
  r.mensajes = Array.isArray(envio.mensajes) ? envio.mensajes : [];
  if (envio.success !== true) {
    r.estado = 'error';
    const errs = Array.isArray(envio.errores) ? envio.errores : [];
    r.errores = errs.length ? errs.map(texto) : ['Trans2000: ' + texto(envio.error || 'respuesta inesperada')];
  }
}
return [{ json: r }];

