const NL = String.fromCharCode(10);
const todos = [$('Resumen Galp').first().json, $('Resumen Area117').first().json, $('Resumen Travis').first().json];
const hasta = $('Calcular fechas').first().json.hasta;
const ayuda = { Galp: 'journalctl -u galp-export', Area117: 'journalctl -u area117-export', Travis: 'journalctl -u travis-export' };
const marca = (r) => (r.estado === 'error' ? 'ERROR' : r.estado === 'sin_datos' ? 'sin facturas' : 'OK');
const hayError = todos.some((r) => r.estado === 'error');
const hayAviso = todos.some((r) => r.avisos.length > 0 || r.omitidas.length > 0);
const suma = (c) => todos.reduce((s, r) => s + (Number(r[c]) || 0), 0);
const asunto = (hayError ? 'ERROR - ' : '') + 'Facturas a Trans2000 (' + hasta + '): ' + todos.map((r) => r.proveedor + ' ' + marca(r)).join(' | ') + (hayAviso && !hayError ? ' | REVISAR AVISOS' : '');
const l = ['Importación semanal de facturas de gastos en Trans2000 - ' + hasta, ''];
for (const r of todos) {
  l.push(r.proveedor.toUpperCase() + ': ' + marca(r) + ' (periodo ' + r.periodo + ')');
  if (r.estado === 'sin_datos') l.push('  Sin facturas nuevas en el periodo.');
  for (const x of r.detalle) l.push('  ' + x);
  for (const x of r.errores) l.push('  ERROR: ' + x);
  if (r.estado === 'error') l.push('  Revisa el servicio en dln8n: ' + ayuda[r.proveedor] + ' (y las capturas state/debug-*.png).');
  if (r.estado === 'error') for (const x of r.mensajes) l.push('  Trans2000: ' + x);
  for (const x of r.avisos) l.push('  AVISO: ' + x);
  for (const x of r.omitidas) l.push('  No enviado: ' + x);
  l.push('');
}
l.push('TOTAL: ' + suma('nuevos') + ' nuevos, ' + suma('actualizados') + ' actualizados, ' + suma('nIncidencias') + ' incidencias.');
const inc = todos.flatMap((r) => r.incidencias.map((i) => ({ proveedor: r.proveedor, incidencia: i })));
if (inc.length) l.push('', 'INCIDENCIAS:', JSON.stringify(inc, null, 2).slice(0, 4000));
l.push('', 'Ejecución de n8n: ' + $execution.id);
return [{ json: { ok: !hayError, asunto, cuerpo: l.join(NL) } }];

